// Priority 5 so local-avatar plugins (priority 10) can still set their own image.
add_filter( 'pre_get_avatar_data', 'perfectpixel_local_avatar_data', 5 );

function perfectpixel_local_avatar_data( $args ) {
	if ( ! empty( $args['url'] ) ) {
		return $args;
	}
	$url = esc_url_raw( trim( '{{local_avatar_url}}' ) );
	if ( ! $url ) {
		$svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" fill="#dcdcde"/><circle cx="32" cy="25" r="12" fill="#a7aaad"/><path d="M10 60c2-13 11-20 22-20s20 7 22 20z" fill="#a7aaad"/></svg>';
		$url = 'data:image/svg+xml;base64,' . base64_encode( $svg );
	}
	$args['url']          = $url;
	$args['found_avatar'] = true;
	return $args;
}
